def compute(vars):
    v1 = vars["v1"]  # 2006, thousands
    v2 = vars["v2"]  # 2007, thousands
    v3 = vars["v3"]  # 2008, thousands
    average_thousands = (v1 + v2 + v3) / 3
    average_millions = average_thousands / 1000
    return {
        "value": average_millions,
        "trace": {
            "average_thousands": average_thousands,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
